def run_bst(root, low, high):
    selected = []
    stack = []
    node = root
    while stack or node is not None:
        while node is not None:
            stack.append(node)
            node = node.left
        node = stack.pop()
        if low < node.val < high and node.val % 2 == 1:
            selected.append(node.val)
        node = node.right
    return selected[::-1]

